const raw = $input.first()?.json ?? {};
let body = raw.body ?? raw;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};
const headers = {};
for (const [key, value] of Object.entries(raw.headers ?? {})) headers[String(key).toLowerCase()] = value;
const authorization = String(headers.authorization ?? '').trim();
const ideaText = typeof body.idea_text === 'string' ? body.idea_text.trim() : '';
const idempotencyKey = String(body.idempotency_key ?? headers['idempotency-key'] ?? '').trim();
const optionalIndustry = typeof body.optional_industry === 'string' ? (body.optional_industry.trim() || null) : null;
const geography = typeof body.geography === 'string' ? (body.geography.trim() || null) : null;
const constraints = body.constraints && typeof body.constraints === 'object' && !Array.isArray(body.constraints) ? body.constraints : {};
const researchAliases={user_research:'customer_demand',customer_research:'customer_demand',customer_demand:'customer_demand',competitor_research:'competitor_intelligence',competitor_intelligence:'competitor_intelligence',market_research:'market_economics',market_economics:'market_economics'};
const rawResearch=Array.isArray(body.requested_research)?body.requested_research:[];
const requestedResearch=[...new Set(rawResearch.map(value=>researchAliases[String(value).toLowerCase()]).filter(Boolean))];
const correlationId = String(headers['x-correlation-id'] ?? `bp-${Date.now()}-${$execution.id}`).slice(0, 200);
const allowedFields = new Set(['idempotency_key', 'idea_text', 'optional_industry', 'geography', 'constraints', 'requested_research']);
const unexpectedFields = Object.keys(body).filter(key => !allowedFields.has(key));
const externalActionFields = ['to', 'recipient', 'phone_number', 'message_to_send', 'email_to_send', 'payment', 'booking', 'publish_to'];
const hasExternalActionPayload = externalActionFields.some(key => Object.prototype.hasOwnProperty.call(body, key));
const actionVerb = '(send|email|message|ping|call|contact|reach out to|post|publish|buy|pay|book|schedule|delete|remove)';
const explicitActionRequest = [
  new RegExp(`^(please\\s+)?${actionVerb}\\b`, 'i'),
  new RegExp(`^(can|could|would|will)\\s+you\\s+${actionVerb}\\b`, 'i'),
  new RegExp(`^i\\s+(want|need|would like)\\s+you\\s+to\\s+${actionVerb}\\b`, 'i')
].some(pattern => pattern.test(ideaText));
const scopeDenied = explicitActionRequest || hasExternalActionPayload;
const errors = [];
if (!/^Bearer\s+\S+$/i.test(authorization)) errors.push('AUTHORIZATION_REQUIRED');
if (scopeDenied) errors.push('OUT_OF_SCOPE_ACTION');
if (unexpectedFields.length) errors.push('UNEXPECTED_FIELDS');
if (ideaText.length < 10 || ideaText.length > 10000) errors.push('IDEA_TEXT_LENGTH');
if (idempotencyKey.length < 8 || idempotencyKey.length > 200 || !/^[A-Za-z0-9._:-]+$/.test(idempotencyKey)) errors.push('IDEMPOTENCY_KEY_FORMAT');
if (optionalIndustry && optionalIndustry.length > 200) errors.push('INDUSTRY_LENGTH');
if (geography && geography.length > 200) errors.push('GEOGRAPHY_LENGTH');
if (Object.keys(constraints).length > 30) errors.push('TOO_MANY_CONSTRAINTS');
if (!Array.isArray(body.requested_research) || requestedResearch.length < 1 || requestedResearch.length > 3 || requestedResearch.length !== rawResearch.length) errors.push('REQUESTED_RESEARCH_INVALID');
const statusCode = scopeDenied ? 422 : (errors.includes('AUTHORIZATION_REQUIRED') ? 401 : 400);
const errorCode = scopeDenied ? 'OUT_OF_SCOPE' : (errors.includes('AUTHORIZATION_REQUIRED') ? 'UNAUTHENTICATED' : 'INVALID_REQUEST');
const safeMessage = scopeDenied
  ? 'Blueprint can research and evaluate a founder idea, but it cannot contact people, send messages, publish, purchase, book, pay, or delete anything.'
  : (errorCode === 'UNAUTHENTICATED' ? 'Please sign in before starting a Blueprint.' : 'Check the idea, idempotency key, and optional fields, then try again.');
return [{ json: {
  valid: errors.length === 0,
  errors,
  scope_denied: scopeDenied,
  unexpected_fields: unexpectedFields,
  status_code: statusCode,
  error_code: errorCode,
  safe_message: safeMessage,
  authorization,
  correlation_id: correlationId,
  request: { idempotency_key: idempotencyKey, idea_text: ideaText, optional_industry: optionalIndustry, geography, constraints, requested_research: requestedResearch }
} }];

const validated = $('Validate and Normalize Start Request').first().json;
const authUser = $input.first()?.json ?? {};
if (!authUser.id) throw new Error('AUTH_CONTEXT_MISSING');
const request = validated.request;
return [{ json: {
  correlation_id: validated.correlation_id,
  authorization: validated.authorization,
  authenticated_user_id: authUser.id,
  rpc_body: {
    p_idempotency_key: request.idempotency_key,
    p_idea_text: request.idea_text,
    p_optional_industry: request.optional_industry,
    p_geography: request.geography,
    p_constraints: {...request.constraints,requested_research:request.requested_research},
    p_original_request: {
      source: 'BP-API-01',
      correlation_id: validated.correlation_id,
      idea_text: request.idea_text,
      optional_industry: request.optional_industry,
      geography: request.geography,
      constraints: request.constraints,
      requested_research: request.requested_research
    }
  }
} }];
